from typing import List
from collections import Counter

def maxScoreWords(words: List[str], letters: List[str], score: List[int]) -> int:
    def can_form_word(word, available_letters):
        word_count = Counter(word)
        for char, count in word_count.items():
            if available_letters[char] < count:
                return False
        return True

    def calculate_score(word, score):
        return sum(score[ord(char) - ord('a')] for char in word)

    def backtrack(index, available_letters, current_score):
        if index == len(words):
            return current_score

        max_score = current_score
        if can_form_word(words[index], available_letters):
            new_available_letters = available_letters.copy()
            for char in words[index]:
                new_available_letters[char] -= 1
            word_score = calculate_score(words[index], score)
            max_score = max(max_score, backtrack(index + 1, new_available_letters, current_score + word_score))

        max_score = max(max_score, backtrack(index + 1, available_letters, current_score))
        return max_score

    available_letters = Counter(letters)
    return backtrack(0, available_letters, 0)
